//! Compile-time build and infrastructure metadata.

/// Build metadata embedded into the RagnorDB server binary.
#[derive(Debug, Clone, Copy)]
pub struct BuildInfo {
    pub ragnordb_version: &'static str,
    pub target: &'static str,
    pub built_at: &'static str,
    pub rust_version: &'static str,
    pub raft_version: &'static str,
    pub wal_version: &'static str,
    pub bloom_version: &'static str,
    pub feature_flags: &'static str,
}

/// Build metadata generated by `build.rs`.
pub const BUILD_INFO: BuildInfo = BuildInfo {
    ragnordb_version: env!("CARGO_PKG_VERSION"),
    target: env!("TARGET"),
    built_at: env!("BUILT_AT"),
    rust_version: env!("RUSTC_VERSION"),
    raft_version: env!("RAFT_VERSION"),
    wal_version: env!("WAL_VERSION"),
    bloom_version: env!("BLOOM_VERSION"),
    feature_flags: env!("RAGNORDB_FEATURES"),
};

impl std::fmt::Display for BuildInfo {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            formatter,
            "RagnorDB v{}
  Target:        {}
  Built:         {}
  Rust:          {}
  Features:      {}
  Infrastructure:
    raft:        {} (path: ../Papers/raft)
    wal:         {} (path: ../wal)
    bloom-bloom: {} (path: ../bloom-bloom)",
            self.ragnordb_version,
            self.target,
            self.built_at,
            self.rust_version,
            self.feature_flags,
            self.raft_version,
            self.wal_version,
            self.bloom_version,
        )
    }
}
